# Key-name validation against keyList.txt
# --------------------------------------------------------------------------

KEYLIST_FILENAME = "keyList.txt"
_KEY_HEADER_RE = re.compile(r"^(?:\[[^\]]+\])+$")
_KEY_NOTE_PREFIXES = (
    "TYPE含", "[animationKey]同", "N为任意内容",
    "可以存在于任何节", "X为任意英文内容",
)

# Compact copy of keyList.txt (note lines removed, then zlib + base64) so the
# script works without the external file.  Fill it with embed_keylist.py.
KEYLIST_INTERNAL_B64 = ""


def internal_keylist_text():
    """Return the embedded key list as plain text."""
    if not KEYLIST_INTERNAL_B64:
        raise ValueError("embedded key list is empty")
    raw = base64.b64decode(KEYLIST_INTERNAL_B64.encode("ascii"))
    return zlib.decompress(raw).decode("utf-8")


def trim_keylist_text(text):
    """Drop blank and documentation lines from a key list."""
    lines = []
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line.startswith(_KEY_NOTE_PREFIXES):
            continue
        lines.append(line)
    return "\n".join(lines)


def parse_keylist_text(text):
    """Parse key list text into [(header_tokens, [key_patterns]), ...]."""
    groups = []
    current = None
    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        if line.startswith(_KEY_NOTE_PREFIXES):
            continue
        if _KEY_HEADER_RE.match(line):
            tokens = re.findall(r"\[([^\]]+)\]", line)
            groups.append((tokens, []))
            current = groups[-1][1]
            continue
        if current is not None:
            current.append(line)
    return groups


def load_keylist(path):
    """Parse a keyList.txt file into [(header_tokens, [key_patterns]), ...]."""
    text = open(path, "rb").read().decode("utf-8-sig", "replace")
    return parse_keylist_text(text)


class KeyValidator(object):
    """Validate key names against the section/key list."""

    def __init__(self, text):
        self.groups = parse_keylist_text(text)
        self.action_keys = set()
        self.canbuild_keys = set()
        for tokens, keys in self.groups:
            if "hiddenAction_NAME" in tokens:
                self.action_keys.update(
                    k for k in keys if re.match(r"^[A-Za-z_]", k))
            if "canBuild_NAME" in tokens:
                self.canbuild_keys.update(
                    k for k in keys if re.match(r"^[A-Za-z_]", k))
        self._cache = {}

    def _regex(self, pattern):
        if pattern.endswith("isLocked:"):
            return None
        if pattern == "animation_TYPE_[animationKey]":
            return r"^animation_(?:idle|moving|attack)_.+$"
        m = re.match(r"^mutatorN_(.*)$", pattern)
        if m:
            return r"^mutator.*_" + re.escape(m.group(1)) + r"$"
        p = pattern
        p = p.replace("#", "ZZHASHZZ").replace("[Language]", "ZZLANGZZ")
        p = p.replace("[actionKey]", "ZZACTZZ").replace("[canBuildKey]", "ZZCBZZ")
        p = p.replace("[animationKey]", "ZZANIMZZ").replace("[time]", "ZZTIMEZZ")
        p = re.escape(p)
        p = p.replace("ZZHASHZZ", r"\d*").replace("ZZLANGZZ", r".+")
        p = p.replace("ZZACTZZ", "(?:" + "|".join(
            re.escape(k) for k in sorted(self.action_keys)) + ")")
        p = p.replace("ZZCBZZ", "(?:" + "|".join(
            re.escape(k) for k in sorted(self.canbuild_keys)) + ")")
        p = p.replace("ZZANIMZZ", r".+").replace("ZZTIMEZZ", r".+")
        return "^" + p + "$"

    @staticmethod
    def _section_matches(tokens, section):
        for token in tokens:
            if token == section:
                return True
            if token.endswith("_NAME") or token.endswith("_NANE"):
                prefix = token.rsplit("_", 1)[0]
                if section.startswith(prefix + "_"):
                    return True
                if prefix == "hiddenAction" and section.startswith("action_"):
                    return True
            if token.endswith("_#"):
                prefix = token.rsplit("_", 1)[0]
                if section.startswith(prefix + "_"):
                    return True
        return False

    def allowed(self, section, key):
        if key.startswith("@"):
            return True
        # template_/comment_ sections hold keys copied from other section
        # types, so they cannot be validated by name.
        if section.startswith(("template_", "comment_")):
            return True
        cached = self._cache.get((section, key))
        if cached is not None:
            return cached
        matched = False
        ok = False
        for tokens, keys in self.groups:
            if not self._section_matches(tokens, section):
                continue
            matched = True
            for pattern in keys:
                if pattern.endswith("isLocked:"):
                    base = pattern.split("name/pos/isLocked:")[0]
                    patterns = [base + s for s in ("name", "pos", "isLocked")]
                else:
                    patterns = [pattern]
                for pat in patterns:
                    rx = self._regex(pat)
                    if rx and re.match(rx, key):
                        ok = True
                        break
                if ok:
                    break
            if ok:
                break
        if not matched:
            ok = True     # no key list for this section -> cannot judge
        self._cache[(section, key)] = ok
        return ok

    def check(self, sections_by_name):
        """Return a list of (file, section, key) that are not allowed."""
        invalid = []
        for file_name, sections in sections_by_name.items():
            for section, kv in sections.items():
                for key in kv:
                    if not self.allowed(section, key):
                        invalid.append((file_name, section, key))
        return invalid


def find_external_keylist(in_path):
    """Find keyList.txt next to the script, then next to the input file."""
    here = os.path.dirname(os.path.abspath(__file__))
    for folder in (here, os.path.dirname(os.path.abspath(in_path))):
        cand = os.path.join(folder, KEYLIST_FILENAME)
        if os.path.isfile(cand):
            return cand
    return None


# --------------------------------------------------------------------------
# Optional expansion of ${...} macros and copyFrom inheritance
# --------------------------------------------------------------------------

_MATH_FUNCS = {"int", "cos", "sin", "sqrt"}
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_.]*")
_TEMPLATE_NAME = "all-units.template"


def normpath(path):
    parts = []
    for seg in path.replace("\\", "/").split("/"):
        if seg in ("", "."):
            continue
        if seg == "..":
            if parts:
                parts.pop()
            continue
        parts.append(seg)
    return "/".join(parts)


def basename(name):
    return name.rsplit("/", 1)[-1]


def is_template_entry(name):
    return basename(name).lower() == _TEMPLATE_NAME


def is_modinfo(name):
    return basename(name).lower() == "mod-info.txt"


def is_unit_file(name):
    """True for files the engine auto-loads as units.

    The engine scans a directory and only the entries ending in ``.ini`` are
    loaded as units (and therefore receive all-units.template); a copyFrom
    source or an all-units.template is read separately and is not a unit.
    """
    return basename(name).lower().endswith(".ini")


def truthy(value):
    return value is not None and value.strip().lower() in ("1", "true", "yes", "on")


def copy_sections(sections):
    return OrderedDict((k, OrderedDict(v)) for k, v in sections.items())


def merge_into(dst, src, inherited=False):
    """Merge src into dst with dst's existing keys taking precedence.

    Mirrors the engine's putIfAbsent merge, including the
    '@copyFrom_skipThisSection' guard on the section already present.

    ``inherited`` is used when merging inherited sources (copyFrom /
    all-units.template).  Two keys only ever belong to the file itself and
    must not be inherited:
      * '[core] dont_load'                 -> a copied unit would stop loading
      * '[...] @copyFrom_skipThisSection'  -> a merge-control flag
    """
    for secname, kv in src.items():
        core = (secname == "core")

        def inherited_only(k):
            return inherited and (k == "@copyFrom_skipThisSection"
                                  or (core and k == "dont_load"))

        if secname not in dst:
            dst[secname] = OrderedDict(
                (k, v) for k, v in kv.items() if not inherited_only(k))
            continue
        if truthy(dst[secname].get("@copyFrom_skipThisSection")):
            continue
        for k, v in kv.items():
            if inherited_only(k):
                continue
            dst[secname].setdefault(k, v)


class FileIndex(object):
    """Case-insensitive lookup of member names inside a mod."""

    def __init__(self, names):
        self.exact = set(names)
        self.lower = {}
        for n in names:
            self.lower.setdefault(n.lower(), n)

    def find(self, name):
        name = normpath(name)
        if name in self.exact:
            return name
        low = name.lower()
        if low in self.lower:
            return self.lower[low]
        for suffix in (".ini", ".template"):
            cand = name + suffix
            if cand in self.exact:
                return cand
            if cand.lower() in self.lower:
                return self.lower[cand.lower()]
        return None


def try_eval(expr):
    """Safely evaluate a small arithmetic expression, else return None.

    A comma means the value is a list (e.g. a footprint "x,y,w,h" or a macro
    fragment like "-1,"), never arithmetic, so it must be left untouched.
    """
    expr = expr.strip()
    if not expr or "," in expr:
        return None
    try:
        node = ast.parse(expr, mode="eval").body
    except SyntaxError:
        return None

    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.BinOp):
            a, b = ev(n.left), ev(n.right)
            if isinstance(n.op, ast.Add):
                return a + b
            if isinstance(n.op, ast.Sub):
                return a - b
            if isinstance(n.op, ast.Mult):
                return a * b
            if isinstance(n.op, ast.Div):
                if b == 0:
                    # Java double division: x/0 -> +-Infinity, 0/0 -> NaN.
                    if a > 0:
                        return math.inf
                    if a < 0:
                        return -math.inf
                    return math.nan
                return a / b
            if isinstance(n.op, ast.Mod):
                return a % b
            if isinstance(n.op, ast.Pow):
                return a ** b
            raise ValueError
        if isinstance(n, ast.UnaryOp):
            v = ev(n.operand)
            if isinstance(n.op, ast.USub):
                return -v
            if isinstance(n.op, ast.UAdd):
                return v
            raise ValueError
        if isinstance(n, ast.Call):
            if not (isinstance(n.func, ast.Name) and len(n.args) == 1):
                raise ValueError
            name = n.func.id
            v = ev(n.args[0])
            if name == "int":
                return int(v)
            if name == "cos":
                return math.cos(v)
            if name == "sin":
                return math.sin(v)
            if name == "sqrt":
                return math.sqrt(v)
            raise ValueError
        raise ValueError

    try:
        return ev(node)
    except Exception:
        return None


def format_number(value):
    if isinstance(value, float):
        if math.isnan(value):
            return "NaN"
        if math.isinf(value):
            return "Infinity" if value > 0 else "-Infinity"
        if value.is_integer():
            return str(int(value))
        return repr(value)
    return str(value)


class Resolver(object):
    """Resolve one mod's ini files to their effective (expanded) content."""

    def __init__(self, parsed, root, use_template):
        self.parsed = parsed
        self.index = FileIndex(parsed.keys())
        self.root = root
        self.use_template = use_template
        self.raw_cache = {}
        self.copyfrom_ok = {}
        self.stack = set()

    # -- path helpers ------------------------------------------------------
    def resolve_target(self, target, cur_name):
        t = target.replace("\\", "/").strip()
        if t.startswith("CORE:"):
            lib = t[5:].strip()
            for key in (lib, lib + ".ini"):
                found = self.index.find("assets/units/" + key)
                if found:
                    return found
            return None
        if t.startswith("ROOT:"):
            rel = normpath(t[5:])
            found = self.index.find(self.root + rel)
            if found:
                return found
            # `ROOT:` is relative to the directory that contains the mod
            # folder, so a reference often looks like
            # "ROOT:<mod folder>/file".  The packer flattens the mod folder
            # away, so retry after dropping leading path segments.
            segs = rel.split("/")
            for i in range(1, len(segs)):
                cand = "/".join(segs[i:])
                found = self.index.find(self.root + cand)
                if found:
                    return found
            return None
        curdir = cur_name.rsplit("/", 1)[0] + "/" if "/" in cur_name else ""
        return self.index.find(curdir + t)

    def find_template(self, cur_name):
        d = cur_name.rsplit("/", 1)[0] if "/" in cur_name else ""
        while True:
            cand = (d + "/" if d else "") + _TEMPLATE_NAME
            found = self.index.find(cand)
            if found:
                return found
            if not d:
                return None
            d = d.rsplit("/", 1)[0] if "/" in d else ""

    # -- main --------------------------------------------------------------
    def raw_merged(self, name):
        """Merge a file with its copyFrom chain, without expanding section
        copies, globals or macros yet (so that inherited directives stay
        available to the receiving file's context).

        all-units.template is deliberately NOT applied here: the engine only
        applies it to a unit it loads itself, never to a copyFrom source it
        merely reads.  resolve() inlines the template at the end instead.
        """
        if name in self.raw_cache:
            return self.raw_cache[name]
        if name in self.stack:          # cycle guard
            return OrderedDict()
        self.stack.add(name)
        own = copy_sections(self.parsed[name])

        copy_targets = []
        copyfrom_ok = True
        core = own.get("core")
        if core and core.get("copyFrom"):
            raw = core["copyFrom"].strip()
            if raw and raw.upper() != "IGNORE":
                for token in raw.split(","):
                    token = token.strip()
                    if not token:
                        continue
                    tname = self.resolve_target(token, name)
                    if tname and tname in self.parsed:
                        copy_targets.append(self.raw_merged(tname))
                    else:
                        copyfrom_ok = False

        # high priority first: own file, then copyFrom targets last-to-first.
        # all-units.template is merged later, in resolve(), as the lowest
        # priority source (the engine's iniobj.put merge order).
        acc = OrderedDict()
        merge_into(acc, own)                       # keep own's own flags
        for target in reversed(copy_targets):
            merge_into(acc, target, inherited=True)

        self.stack.discard(name)
        self.raw_cache[name] = acc
        self.copyfrom_ok[name] = copyfrom_ok
        return acc

    def resolve(self, name):
        """Final effective content for one file."""
        acc = copy_sections(self.raw_merged(name))
        # Only a unit the engine loads directly receives its directory's
        # all-units.template, and only when it is not marked dont_load.  A
        # copyFrom source is read raw by the engine, so a base config must
        # never absorb a template even when it is expanded on its own; only
        # real .ini units get it.
        if (self.use_template and is_unit_file(name)
                and not truthy((acc.get("core") or {}).get("dont_load"))):
            tname = self.find_template(name)
            if tname and tname in self.parsed:
                merge_into(acc, self.raw_merged(tname), inherited=True)
        self.resolve_section_copies(acc)
        globals_ = self.collect_globals(acc)
        self.resolve_macros(acc, globals_)
        if self.copyfrom_ok.get(name, True) and "core" in acc and "copyFrom" in acc["core"]:
            del acc["core"]["copyFrom"]
        # Once everything is expanded, the macro definitions are no longer
        # needed.  Keep them only when some ${...} could not be resolved, so
        # the engine can still finish the job at runtime.
        has_macro = any("${" in v for sec in acc.values() for v in sec.values())
        if not has_macro:
            for sec in acc.values():
                for key in list(sec.keys()):
                    if key.startswith("@define ") or key.startswith("@global "):
                        del sec[key]
        return acc

    @staticmethod
    def section_targets(name, sec):
        """Collect the sections this section inherits from.

        '@copyFromSection' lists explicit section names; the plain 'copyFrom'
        key used inside indexed parts (turret_R, leg_2, projectile_3, ...)
        names a sibling by suffix: `[leg_2] copyFrom: 1` -> `leg_1`.
        """
        targets = []
        explicit = sec.get("@copyFromSection")
        if explicit and explicit.strip().upper() != "IGNORE":
            for token in explicit.split(","):
                token = token.strip()
                if token:
                    targets.append(token)
        sibling = sec.get("copyFrom")
        if sibling and "_" in name:
            prefix = name[:name.index("_")]
            for token in sibling.split(","):
                token = token.strip()
                if token:
                    targets.append(prefix + "_" + token)
        return targets

    def resolve_section_copies(self, sections):
        resolved = {}
        visiting = set()

        def ensure(name):
            if name in resolved:
                return
            if name in visiting:
                return
            sec = sections.get(name)
            if sec is None:
                resolved[name] = None
                return
            visiting.add(name)
            copied = OrderedDict()
            targets = self.section_targets(name, sec)
            all_found = bool(targets)
            for token in targets:
                ensure(token)
                tsec = resolved.get(token)
                if tsec:
                    copied.update(tsec)     # later target wins
                else:
                    all_found = False
            # merge-control flags belong to the section itself, not to the
            # sections it copies from.
            copied.pop("@copyFrom_skipThisSection", None)
            # engine order: own keys first (original positions), then the
            # missing keys copied from the target section(s).
            merged = OrderedDict()
            for k, v in sec.items():
                if k in ("@copyFromSection", "copyFrom"):
                    continue
                merged[k] = v
            for k, v in copied.items():
                merged.setdefault(k, v)
            if not all_found:
                # keep an unresolved directive so the engine can retry it
                for key in ("@copyFromSection", "copyFrom"):
                    if key in sec:
                        merged[key] = sec[key]
            resolved[name] = merged
            visiting.discard(name)

        for name in list(sections.keys()):
            ensure(name)
        for name, value in resolved.items():
            if value is not None:
                sections[name] = value

    def collect_globals(self, sections):
        globals_ = {}
        for sec in sections.values():
            for key, value in sec.items():
                if key.startswith("@global ") and value.strip() != "IGNORE":
                    globals_[key[len("@global "):]] = value
        return globals_

    def resolve_macros(self, sections, globals_):
        for _ in range(10):                     # bounded passes for nesting
            changed = False
            for secname, sec in sections.items():
                for key, value in list(sec.items()):
                    new = self.expand(value, secname, sec, sections, globals_)
                    if new is not None and new != value:
                        sec[key] = new
                        changed = True
            for key, value in list(globals_.items()):
                new = self.expand(value, None, {}, sections, globals_)
                if new is not None and new != value:
                    globals_[key] = new
                    changed = True
            if not changed:
                break

    def expand(self, value, secname, sec, sections, globals_):
        if "${" not in value:
            return value
        out = []
        i = 0
        n = len(value)
        while True:
            start = value.find("${", i)
            if start < 0:
                out.append(value[i:])
                break
            out.append(value[i:start])
            end = value.find("}", start + 2)
            if end < 0:
                out.append(value[start:])
                break
            replacement = self.resolve_matcher(
                value[start + 2:end], secname, sec, sections, globals_)
            if replacement is None:
                out.append(value[start:end + 1])   # leave unresolved
            else:
                out.append(replacement)
            i = end + 1
        return "".join(out)

    def resolve_matcher(self, inner, secname, sec, sections, globals_):
        inner = inner.strip()
        result = []
        pos = 0
        failed = False

        def lookup(token):
            if token in _MATH_FUNCS:
                return token
            if "." in token:
                secn, key = token.split(".", 1)
                table = sec if (secn == "section" or secn == secname) else sections.get(secn)
                if table is None or key not in table:
                    return None
                return table[key]
            value = sec.get("@define " + token)
            if value is None:
                value = globals_.get(token)
            if value is None:
                value = sec.get(token)
            return value

        for match in _IDENT_RE.finditer(inner):
            result.append(inner[pos:match.start()])
            token = match.group(0)
            value = lookup(token)
            if value is None:
                failed = True
                result.append(token)
            else:
                result.append(value)
            pos = match.end()
        result.append(inner[pos:])
        text = "".join(result)
        if failed:
            return None

        if any(ch in text for ch in "+-*/%^()"):
            py = text.replace("^", "**")
            value = try_eval(py)
            if value is not None:
                return format_number(value)
        return text


def detect_root(names):
    candidates = sorted((n for n in names if is_modinfo(n)), key=len)
    if candidates:
        top = candidates[0]
        return top[:len(top) - len("mod-info.txt")]
    return ""



def safe_member_path(root, name):
    """Join root + name, refusing to escape root."""
    parts = [p for p in name.replace("\\", "/").split("/") if p not in ("", ".")]
    if any(p == ".." for p in parts):
        raise ValueError("unsafe path: " + name)
    return os.path.join(root, *parts)


def read_text(data):
    """Decode text files as UTF-8, falling back to common GBK."""
    for enc in ("utf-8-sig", "utf-8", "gbk", "big5"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", "replace")


def open_zip(path):
    return zipfile.ZipFile(path, "r")


